print("=== Comprehensive audit of large training/strength resource folders ===\n")

# Focus on the Athletic Performance folder which seems to be a major resource
key_paths = {
    "Athletic Performance": "G:/My Drive/Athletic Performance & Sports Science",
    "Strength & Conditioning": "G:/My Drive/Athletic Performance & Sports Science/Strength and Conditioning Resources",
